{
  "item_id": "PRISMA_2020_13a",
  "elements": [
    {
      "element_id": "prisma_2020_13a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "We reviewed the exposure and outcome definitions and reported risk factors in each study. Where there were several studies with similar exposure definitions, data were included in a random effects meta-analysis for the respective exposure and CKDu and displayed in a forest plot.",
      "reason": "The methods describe a process for deciding synthesis eligibility: exposure/outcome definitions were reviewed and studies with similar exposure definitions were grouped into random-effects meta-analyses. Results (text_9) further note which risk factors had sufficient data for meta-analysis. However, the description is brief and does not fully detail tabulation/comparison of study characteristics against planned synthesis groups, so it is only partially reported."
    }
  ],
  "confidence": 70
}

{
  "item_id": "PRISMA_2020_13b",
